#!/bin/sh
# Verifier entrypoint. Generated by eval-harvest emit; do not edit by hand.
#
# Harbor discards this script's exit code (verifier/verifier.py:199-202) and reads only the reward
# file, so the reward is written on every path: score.py writes /logs/verifier/reward.json itself,
# and if it cannot run at all this wrapper writes a zero reward rather than leaving Harbor to error
# the trial with no signal.
set -u

mkdir -p /logs/verifier

# Scrub the reward-kit override variables so the judge model pinned in judge.toml is the one that
# runs: REWARDKIT_JUDGE/REWARDKIT_MODEL silently override a task-pinned judge otherwise, and a
# judge that is not pinned is not pinned (finding_matching.py:122, ADR-5).
unset REWARDKIT_JUDGE REWARDKIT_MODEL REWARDKIT_TEMPERATURE OPENAI_API_BASE OPENAI_BASE_URL OPENAI_MODEL

score_status=0
python3 /tests/score.py || score_status=$?

if [ "$score_status" -ne 0 ] && [ ! -f /logs/verifier/reward.json ]; then
  # score.py failed before writing a reward: record a zero rather than nothing, so the trial scores
  # 0 instead of erroring with no signal.
  printf '{"coverage_required": 0, "coverage_all": 0, "precision_strict": 0, "precision_adjudicated": 0}' \
    > /logs/verifier/reward.json
fi

# Exit 0 regardless: the reward file is the signal; a non-zero exit here would only mislead a human
# reading the trial log.
exit 0
